function validate(r,s,input){if(r){DivineSelection.apply(s,r,input);NPCLife.validateScene(s,r);NPCGoalActions.apply(s,r,input);}Escort.validateScene(s,r);Personal.validateScene(s,r);Mining.validateScene(s,r);if(!r||!['earth','fantasy'].includes(r.era)||!['dialogue','exploration','combat'].includes(r.scene)||!Array.isArray(r.panels)||!r.panels.length||r.panels.length>6)throw Error('장면 응답 형식이 올바르지 않습니다.');if(!Number.isInteger(r.elapsedMinutes)||r.elapsedMinutes<0||r.elapsedMinutes>15)throw Error('장면 시간 범위가 잘못되었습니다.');if(CombatRules.fatigue(s.player).exhausted&&(r.location!==s.location||r.combat?.importance!=='none'&&s.combat?.status!=='playing'))throw Error('탈진 상태에서는 먼저 실제 수면이 필요합니다.');const validLoc=r.era==='earth'?earth:G.records.map(p=>p.id);if(!validLoc.includes(r.location))throw Error('등록되지 않은 장소입니다.');if(r.location!==s.location&&r.era===s.era&&!/가|이동|나가|내리|타|걷|걸|향|따라|계속/.test(input))throw Error('요청하지 않은 장소 이동을 보류했습니다.');const from=G.records.find(p=>p.id===s.location),to=G.records.find(p=>p.id===r.location);if(s.era==='fantasy'&&from&&to&&from.continent!==to.continent&&s.ledger.filter(e=>/출항|승선|항해|비행선|마차|육로|여정/.test(e.text)).length<2)throw Error('대륙 이동에 필요한 여정이 진행되지 않았습니다.');if(s.era==='fantasy'&&r.era!=='fantasy')throw Error('현실 복귀는 아직 구현되지 않았습니다.');if(s.era==='earth'&&r.era==='fantasy'&&!(s.ledger.filter(e=>/이상|깜빡|진동|끊|균열|빛/.test(e.text)).length>=2&&/전이|전송|이세계|빛.*들어|계속|넘어/.test(input)))throw Error('전이 사건의 진행 근거가 아직 부족합니다.');if(!Array.isArray(r.present)||r.present.length>8||r.present.some(id=>!ids.includes(id)||id==='taei'||r.era==='earth'&&id==='zero'||!Origins.allowed(id,{era:r.era})))throw Error('현재 세계에 등장할 수 없는 인물입니다.');if(!Array.isArray(r.locals)||r.locals.length>6||r.locals.some(n=>!/^npc_[a-z0-9_-]{1,32}$/.test(n.id)||typeof n.name!=='string'||!n.name.trim()||n.name.length>30||D.catalog.some(c=>c.name===n.name)||typeof n.role!=='string'||n.role.length>150||(s.npcRegistry||[]).some(old=>old.id===n.id&&old.name!==n.name)))throw Error('주변 인물의 식별 정보가 잘못되었습니다.');if(!Array.isArray(r.party)||r.party.length>3||new Set(r.party).size!==r.party.length||r.party.some(id=>!ids.includes(id)||id==='taei'||!Origins.allowed(id,{era:r.era})))throw Error('파티 정보가 잘못되었습니다.');const joined=r.party.filter(id=>!(s.party||[]).includes(id));if(joined.some(id=>!r.present.includes(id))||joined.length&&(!/같이|함께|동행|합류|파티/.test(input)||/않|말자|싫|거절/.test(input)))throw Error('사용자가 선택하지 않은 파티 합류를 보류했습니다.');if(!ids.includes(r.focus)||r.focus!=='taei'&&!r.present.includes(r.focus))throw Error('화면 인물이 현장에 없습니다.');for(const p of r.panels)if(!p||p.speaker==='taei'||p.speaker!=='narrator'&&!r.present.includes(p.speaker)&&!r.locals.some(n=>n.id===p.speaker)||typeof p.text!=='string'||!p.text.trim()||p.text.length>320)throw Error('플레이어의 결정을 대신 쓰거나 잘못된 대사입니다.');if(!Array.isArray(r.choices)||r.choices.length>3||r.choices.some(x=>typeof x!=='string'||x.length>80))throw Error('선택지 형식이 잘못되었습니다.');const proof=r.panels.map(p=>p.text).join('\n');if(!Array.isArray(r.facts)||r.facts.length>4||r.facts.some(f=>!f||typeof f.text!=='string'||f.text.length>240||typeof f.evidence!=='string'||f.evidence.length<3||!proof.includes(f.evidence)))throw Error('기억에 저장할 사실의 인용 근거가 없습니다.');if(!Array.isArray(r.threads)||r.threads.length>4||r.threads.some(t=>!/^[-a-zA-Z0-9]{1,40}$/.test(t.id)||typeof t.text!=='string'||t.text.length>180||!['open','resolved'].includes(t.status)||t.status==='resolved'&&!s.threads.some(old=>old.id===t.id&&old.status==='open')))throw Error('사건 기록 형식이 잘못되었습니다.');const c=r.combat;if(!c||!['none','ordinary','major'].includes(c.importance)||!['observe','attack','defend','move','flee','talk'].includes(c.intent)||!Number.isInteger(c.target)||c.target<0||c.target>5||!Array.isArray(c.monsters)||c.monsters.length>6||c.monsters.some(id=>!monsterIds.includes(id))||typeof c.reason!=='string'||c.reason.length>300||!['none','danger','objective','irreversible','boss'].includes(c.stakes)||!Array.isArray(c.evidenceIds))throw Error('전투 판단 형식이 잘못되었습니다.');if(c.importance!=='none'&&(r.era!=='fantasy'||r.scene!=='combat'||!c.monsters.length))throw Error('전투가 가능한 장소와 적이 필요합니다.');if(r.scene==='combat'&&c.importance==='none')throw Error('전투 장면에 전투 판단이 없습니다.');if(s.combat?.status==='playing'&&JSON.stringify(c.monsters)!==JSON.stringify(s.combat.monsters))throw Error('진행 중인 적을 바꿀 수 없습니다.');if(s.combat?.status==='playing'&&c.importance==='none')throw Error('진행 중인 전투는 판정 없이 끝낼 수 없습니다.');if(c.importance==='major'&&(!['objective','irreversible','boss'].includes(c.stakes)||!c.reason.trim()||!c.evidenceIds.length||c.evidenceIds.some(id=>!s.ledger.some(e=>e.id===id))))throw Error('중요 전투의 누적 사건 근거가 없습니다.');StorySkills.proposals(s,r);return r;}
